solution.js:
const daftarSoal = [
  { tanya: "Tag apa yang menghubungkan HTML ke file CSS eksternal?", opsi: ["<script>", "<link>", "<style src>"], benar: 1 },
  { tanya: "Method apa yang memasang atau melepas class dalam satu panggilan?", opsi: ["classList.toggle()", "style.toggle()", "className.add()"], benar: 0 },
  { tanya: "Atribut apa yang membuat <script> di <head> menunggu HTML selesai dibaca?", opsi: ["async", "lazy", "defer"], benar: 2 },
  { tanya: "Apa hasil querySelector bila elemennya belum ada?", opsi: ["undefined", "null", "Error 404"], benar: 1 },
];

const pertanyaan = document.querySelector("#pertanyaan");
const tombolOpsi = document.querySelectorAll("#opsi .opsi");
const hasil = document.querySelector("#hasil");
const skorEl = document.querySelector("#skor");
const nomorEl = document.querySelector("#nomor");
const berikutnya = document.querySelector("#berikutnya");
const tombolTema = document.querySelector("#tombol-tema");

let indeks = 0;
let skor = 0;

function tampilkanSoal() {
  const soal = daftarSoal[indeks];
  pertanyaan.textContent = soal.tanya;
  nomorEl.textContent = indeks + 1;
  hasil.textContent = "";
  tombolOpsi.forEach((tombol, i) => {
    tombol.textContent = soal.opsi[i];
    tombol.classList.remove("benar", "salah");
    tombol.disabled = false;
    if (i === soal.benar) {
      tombol.dataset.benar = "true";
    } else {
      delete tombol.dataset.benar;
    }
  });
}

tombolOpsi.forEach((tombol) => {
  tombol.addEventListener("click", () => {
    const tepat = tombol.dataset.benar === "true";
    tombol.classList.add(tepat ? "benar" : "salah");
    tombolOpsi.forEach((t) => {
      t.disabled = true;
    });
    if (tepat) {
      skor++;
      skorEl.textContent = skor;
      hasil.textContent = "Benar! Mantap.";
    } else {
      const kunci = document.querySelector('#opsi [data-benar="true"]');
      hasil.textContent = "Salah, jawabannya " + kunci.textContent;
    }
  });
});

berikutnya.addEventListener("click", () => {
  indeks = (indeks + 1) % daftarSoal.length;
  tampilkanSoal();
});

tombolTema.addEventListener("click", () => {
  const akar = document.documentElement;
  const sedangGelap = akar.dataset.tema === "gelap";
  if (sedangGelap) {
    delete akar.dataset.tema;
  } else {
    akar.dataset.tema = "gelap";
  }
  tombolTema.textContent = sedangGelap ? "Mode gelap" : "Mode terang";
});

tampilkanSoal();

